PRAGMA foreign_keys=ON;
BEGIN TRANSACTION;
CREATE TABLE cities (
       id                INTEGER PRIMARY KEY,
       name              TEXT,
       country           TEXT,
       population        INTEGER,
       latitude          DOUBLE,
       longitude         DOUBLE
);
CREATE TABLE connections (
       id_city_1      INTEGER,
       id_city_2      INTEGER,
       distance       DOUBLE,
       PRIMARY KEY    (id_city_1, id_city_2),
       FOREIGN KEY    (id_city_1) REFERENCES cities(id),
       FOREIGN KEY    (id_city_2) REFERENCES cities(id)
);
COMMIT;
